(cii.REGIST_BANK_CODE = #{item.registBankCode} and cii.INDENTIFY_MARK=#{item.indentifyMark} and cii.PRODID=#{item.prodid} and DATE_FORMAT(cii.HOLD_DATE,'%Y-%m-%d')=DATE_FORMAT(#{item.holdDate},'%Y-%m-%d') and cii.CCY=#{item.ccy} and cii.STATUS=#{item.status})
